// Anti-tamper client side shared by every online board game (rules: <game>/database.rules.json, generated by shared/tools/secrules.py).
//
// Two protocols, chosen per session by probing the database:
//   legacy — the published rules are the old ones (secv is not readable): everything works exactly as before.
//   secure — the new rules are published: a rated game is linked to both players (open/<uid> = gid) when it is created, each side
//            reports its own result (games/<gid>/res/<uid> = { s, t }), and a player's rating changes only in one atomic write
//            that settles the linked game: players/<uid> (Elo, games + 1, …) + open/<uid> = null + pc/<uid>/<opp> (max 3 a day).
//            A game whose result can not count (reports disagree, the loser never joined, stale, pair limit) is "void": the link is
//            cleared without a rating change. Unsettled links are retried at start-up, every minute and before a rated search, so a
//            result is never lost when a tab closes or the connection drops (the server keeps the state; nothing is only local).
// Also: Firebase App Check (reCAPTCHA v3) when a site key is configured (window.FIREBASE_APPCHECK_SITE_KEY in <game>/firebase-config.js;
// null = skipped). Local testing: ?appcheckdebug=1 (or localStorage 'appcheck-debug' = a registered debug token) on localhost.
(function () {
  'use strict';
  if (window.OnlineSec) return;
  const FB = 300000, STALE = 3 * 3600000, PAIR_MAX = 3, DAY = 86400000, WAIT = 12000;
  const Q = new URLSearchParams(location.search);

  // ------------------------------------------------------------------ App Check
  const loaded = {};
  function loadScript(src) { const C = window.__fbScripts = window.__fbScripts || {}; return C[src] || (C[src] = new Promise((res, rej) => { const s = document.createElement('script'); s.src = src; s.onload = res; s.onerror = () => rej(new Error('load ' + src)); document.head.appendChild(s); })); }
  // activate App Check for a firebase (compat) app before its database is used. Never throws: without a key (or on any error) the
  // page keeps working; the console tells why (enforcement in the console then decides whether requests are accepted).
  async function appCheck(app, siteKey, fbVer) {
    if (!siteKey || !app) return false;
    const name = app.name || '[DEFAULT]';
    if (loaded[name]) return loaded[name];
    return (loaded[name] = (async () => {
      try {
        await loadScript(`https://www.gstatic.com/firebasejs/${fbVer || '10.12.2'}/firebase-app-check-compat.js`);
        const local = /^(localhost|127\.0\.0\.1|\[::1\])$/.test(location.hostname);
        if (local) {
          let tok = null; try { tok = localStorage.getItem('appcheck-debug'); } catch (e) {}
          if (tok || Q.has('appcheckdebug')) self.FIREBASE_APPCHECK_DEBUG_TOKEN = tok || true;   // true: the SDK prints a token to register in the console
        }
        const ac = app.appCheck ? app.appCheck() : firebase.appCheck(app);
        ac.activate(new firebase.appCheck.ReCaptchaV3Provider(siteKey), true);
        return true;
      } catch (e) { console.warn('App Check', e); return false; }
    })());
  }

  // ------------------------------------------------------------------ protocol
  async function detect(db, mock) {
    if (mock) return Q.has('secold') ? 'legacy' : 'secure';
    try { await db.get('secv'); return 'secure'; } catch (e) { return 'legacy'; }
  }
  const kOf = (games, oppGames) => (games < 10 ? 40 : games < 30 ? 32 : 24) * (typeof oppGames === 'number' && oppGames >= 3 ? 1 : 0.5);
  const elo = (my, opp, s, games, oppGames) => Math.round(my + kOf(games, oppGames) * (s - 1 / (1 + Math.pow(10, (opp - my) / 400))));
  const oppOf = (G, uid) => (G.b === uid ? G.w : G.b);
  const has = (o, k) => !!(o && Object.prototype.hasOwnProperty.call(o, k) && o[k] !== null && o[k] !== undefined);
  // what game G means for uid's rating — the same conditions as the rules. → { s } | { void: why } | { wait: why } | { report: true }
  // oppHere: the opponent is in presence (only matters for a lone report); opts.match: backgammon (an 'over' counts only with mo)
  function outcome(G, uid, now, oppHere, opts) {
    if (!G) return { void: 'gone' };
    if (G.rated !== true) return { void: 'unrated' };
    if (G.b !== uid && G.w !== uid) return { void: 'gone' };
    const st = G.status, opp = oppOf(G, uid), j = G.j || {}, res = G.res || {}, abandon = !!(opts && opts.abandon);
    const forced = st === 'timeout' || (abandon && st === 'abandon');
    if (st === 'resign') return { s: G.loser === uid ? 0 : 1 };
    if (forced) { if (!has(j, G.loser)) return { void: 'noshow' }; return { s: G.draw === true ? 0.5 : G.loser === uid ? 0 : 1 }; }
    if (st === 'draw' && opts && opts.draw) return { s: 0.5 };
    const stale = now - (G.t || 0) > STALE;
    if (st === 'over') {
      const a = res[uid], b = res[opp];
      if (a && b && a.s + b.s !== 1) return { void: 'mismatch' };
      if (!has(j, uid) && !a) return { void: 'noshow' };
      if (!has(j, opp) && !b) return { void: 'noshow' };
      if (opts && opts.match && G.mo !== true) return stale ? { void: 'stale' } : { wait: 'match' };
      if (a && b) return { s: a.s };
      if (!a && !b) return stale ? { void: 'stale' } : { report: true };
      if (a) return now - a.t > FB && !oppHere ? { s: a.s } : { wait: 'report' };
      return now - b.t > FB ? { s: 1 - b.s } : { report: true };
    }
    if (st === 'play') return stale ? { void: 'stale' } : { wait: 'play' };
    return { void: 'unknown' };
  }

  // one settler per page and game record: { ctx } → see settle()
  function make(ctx) {
    // ctx: { db, uid(), mock, opts: { match, draw, abandon }, onProfile(p), decorate(np, p, G, s, nr), initial }
    let mode = null, timer = 0;
    const busy = new Map();
    const S = {
      get mode() { return mode; },
      async init() { mode = await detect(ctx.db(), ctx.mock); clearInterval(timer); if (mode === 'secure') { timer = setInterval(() => S.resolve().catch(() => {}), 60000); setTimeout(() => S.resolve().catch(() => {}), 1500); } return mode; },
      secure: () => mode === 'secure',
      // create a rated game record linked to both players (secure) / as before (legacy)
      async createRated(gid, rec) {
        const db = ctx.db();
        if (mode !== 'secure') return db.set('games/' + gid, rec);
        return db.update('/', { ['games/' + gid]: rec, ['open/' + rec.b]: gid, ['open/' + rec.w]: gid });
      },
      // a candidate in the lobby who still has an unsettled rated game can not be matched (the rules refuse the game)
      async blocked(u) { if (mode !== 'secure') return false; try { return !!(await ctx.db().get('open/' + u)); } catch (e) { return false; } },
      // my own result report (write-once); s = 1 / 0.5 / 0 from my own view of the board
      async report(gid, s) {
        if (mode !== 'secure' || ![0, 0.5, 1].includes(s)) return false;
        const db = ctx.db(), uid = ctx.uid();
        try { const r = await db.txn('games/' + gid + '/res/' + uid, cur => (cur === null ? { s, t: db.stamp() } : undefined)); return !!r.committed; } catch (e) { console.warn(e); return false; }
      },
      // mark this participant as having joined the game (timeouts / abandons only count against a player who joined)
      join(gid) {
        if (mode !== 'secure') return;
        const db = ctx.db(), uid = ctx.uid(), p = 'games/' + gid + '/j/' + uid;
        const put = () => db.txn(p, cur => (cur === true ? undefined : true)).catch(() => {});
        put();
        setTimeout(() => { db.get(p).then(v => { if (v !== true && ctx.uid() === uid) put(); }).catch(() => {}); }, 2500);   // verify (lost write / reconnect)
      },
      // settle gid for me: report my own view first when the result needs it, wait up to WAIT for the outcome, then write.
      // → { old, now, rated, note } (note: why there is no rating change: mismatch | limit | pending | void | legacy)
      async settle(gid, game, score, opt) {
        const db = ctx.db(), uid = ctx.uid();
        const prof = await db.get('players/' + uid);
        const old = prof && typeof prof.rating === 'number' ? prof.rating : ctx.initial;
        const base = { old, now: old, rated: false };
        if (!game || game.rated !== true) return base;
        if (busy.has(gid)) return busy.get(gid);
        const p = (async () => {
          let open = await db.get('open/' + uid);
          const opts = ctx.opts || {};
          if (open !== gid) {      // already settled (a reload) / voided / a game from before the new rules
            if (prof && prof.last === gid) return { old, now: old, rated: true };
            const oc = outcome(await db.get('games/' + gid), uid, db.now(), false, opts);
            return Object.assign(base, { note: oc.void === 'mismatch' ? 'mismatch' : 'void' });
          }
          let G;
          // wait for the opponent's report (both clients normally report within a second)
          const t0 = Date.now();
          let oc;
          for (;;) {
            G = await db.get('games/' + gid);
            // score: my own view (1 / 0.5 / 0), null = the board is not finished here (the end is disputed: claim the win), undefined = unknown
            if (G && G.status === 'over' && !(G.res && G.res[uid]) && score !== undefined) { await S.report(gid, score === null ? 1 : score); G = await db.get('games/' + gid); }
            const opp = G ? oppOf(G, uid) : null;
            const here = opp ? !!(await db.get('presence/' + opp).catch(() => null)) : false;
            oc = outcome(G, uid, db.now(), here, opts);
            if (!oc.wait && !oc.report) break;
            if (Date.now() - t0 > ((opt && opt.wait) != null ? opt.wait : WAIT)) break;
            await new Promise(r => setTimeout(r, 1000));
          }
          if (oc.void) { await clear(uid); return Object.assign(base, { note: oc.void === 'mismatch' ? 'mismatch' : oc.void === 'unrated' ? undefined : 'void' }); }
          if (oc.s === undefined) return Object.assign(base, { note: 'pending' });
          return write(gid, G, oc.s, base);
        })();
        busy.set(gid, p);
        try { return await p; } finally { busy.delete(gid); }
      },
      // settle (or void) whatever is still linked to me — start-up, every minute, before a rated search. → true when nothing is open
      async resolve() {
        if (mode !== 'secure') return true;
        const db = ctx.db(), uid = ctx.uid(); if (!uid) return true;
        const gid = await db.get('open/' + uid);
        if (!gid) return true;
        const G = await db.get('games/' + gid);
        if (G && G.status === 'play' && db.now() - (G.t || 0) <= STALE) return false;     // still being played
        const r = await S.settle(gid, G || { rated: true }, undefined, { wait: 0 });
        return !r.note || r.note !== 'pending' ? !(await db.get('open/' + uid)) : false;
      },
    };
    async function clear(uid) { try { await ctx.db().remove('open/' + uid); } catch (e) { console.warn(e); } }
    async function write(gid, G, s, base) {
      const db = ctx.db(), uid = ctx.uid(), opp = oppOf(G, uid), oppRating = G.b === uid ? G.wr : G.br;
      for (let tries = 0; tries < 3; tries++) {
        const p = await db.get('players/' + uid);
        if (!p) return base;
        const oppGames = await db.get('players/' + opp + '/games').catch(() => null);
        const pc = await db.get('pc/' + uid + '/' + opp).catch(() => null);
        const d = Math.floor(db.now() / DAY), n = pc && pc.d === d ? pc.n + 1 : 1;
        if (n > PAIR_MAX) { await clear(uid); return Object.assign(base, { note: 'limit' }); }
        const games = typeof p.games === 'number' ? p.games : 0;
        const nr = elo(p.rating, typeof oppRating === 'number' ? oppRating : ctx.initial, s, games, oppGames);
        const np = Object.assign({}, p, { rating: nr, games: games + 1, last: gid });
        const c = k => (typeof p[k] === 'number' ? p[k] : 0);
        np.wins = c('wins') + (s === 1 ? 1 : 0); np.losses = c('losses') + (s === 0 ? 1 : 0); np.draws = c('draws') + (s === 0.5 ? 1 : 0);
        if (ctx.decorate) ctx.decorate(np, p, G, s, nr);
        try {
          await db.update('/', { ['players/' + uid]: np, ['open/' + uid]: null, ['pc/' + uid + '/' + opp]: { d, n } });
          ctx.onProfile && ctx.onProfile(np);
          return { old: p.rating, now: nr, rated: true, s };
        } catch (e) {
          console.warn('settle', e);
          if ((await db.get('open/' + uid)) !== gid) { const q = await db.get('players/' + uid); return q && q.last === gid ? { old: p.rating, now: q.rating, rated: true } : base; }
          await new Promise(r => setTimeout(r, 800 + 400 * tries));
        }
      }
      return Object.assign(base, { note: 'pending' });
    }
    return S;
  }

  // ------------------------------------------------------------------ account switch (anonymous → existing Google account)
  // before leaving the old uid: a private snapshot of its record keyed by a one-time secret; after the switch the new uid takes it over
  async function xferOut(db, uid) {
    const p = await db.get('players/' + uid);
    if (!p) return null;
    const a = new Uint8Array(16); crypto.getRandomValues(a);
    const k = Array.from(a, b => b.toString(16).padStart(2, '0')).join('');
    const n = v => (typeof v === 'number' ? v : null);
    await db.set('xfer/' + uid, { k, r: p.rating, g: n(p.games), w: n(p.wins), l: n(p.losses), d: n(p.draws) });
    return { f: uid, k, p };
  }
  async function xferIn(db, uid, x) {
    const p = Object.assign({}, x.p);
    delete p.last;
    await db.update('/', { ['players/' + uid]: p, ['xclaim/' + uid]: { f: x.f, k: x.k } });
  }

  // ------------------------------------------------------------------ messages (10 languages; the page's <html lang>)
  const M = {
    mismatch: { ja: '結果が一致しないためレート対象外', en: 'Results did not match — unrated', zh: '双方结果不一致，不计入等级分', ko: '결과가 일치하지 않아 레이팅 미반영', es: 'Los resultados no coinciden: sin puntuar', fr: 'Résultats divergents : partie non classée', pt: 'Resultados não conferem: sem ranking', de: 'Ergebnisse stimmen nicht überein – ungewertet', hi: 'नतीजे मेल नहीं खाए — रेटिंग नहीं बदली', ar: 'النتيجتان غير متطابقتين — غير مصنّفة' },
    pending: { ja: '相手の結果確認待ち（確定後に自動でレートに反映）', en: 'Waiting for the opponent to confirm (the rating updates automatically)', zh: '等待对方确认结果（确认后自动更新等级分）', ko: '상대의 결과 확인 대기 중 (확정 후 자동 반영)', es: 'Esperando la confirmación del rival (la puntuación se actualizará sola)', fr: "En attente de la confirmation de l'adversaire (classement mis à jour automatiquement)", pt: 'Aguardando a confirmação do adversário (o rating atualiza sozinho)', de: 'Warte auf Bestätigung des Gegners (Wertung folgt automatisch)', hi: 'प्रतिद्वंद्वी की पुष्टि का इंतज़ार (रेटिंग अपने-आप अपडेट होगी)', ar: 'بانتظار تأكيد الخصم (يُحدَّث التصنيف تلقائيًا)' },
    limit: { ja: '同じ相手とのレート戦は1日3局まで（レート変動なし）', en: 'Max 3 rated games a day against the same opponent — unrated', zh: '同一对手每天最多3局计分对局（不计分）', ko: '같은 상대와의 레이팅 대국은 하루 3국까지 (변동 없음)', es: 'Máximo 3 partidas puntuables al día contra el mismo rival: sin puntuar', fr: 'Maximum 3 parties classées par jour contre le même adversaire : non classée', pt: 'Máximo de 3 partidas ranqueadas por dia contra o mesmo adversário: sem ranking', de: 'Höchstens 3 gewertete Partien pro Tag gegen denselben Gegner – ungewertet', hi: 'एक ही प्रतिद्वंद्वी से दिन में अधिकतम 3 रेटेड गेम — रेटिंग नहीं बदली', ar: 'حد أقصى 3 مباريات مصنّفة يوميًا ضد الخصم نفسه — غير مصنّفة' },
    void: { ja: 'この対局はレート対象外になりました', en: 'This game was not rated', zh: '本局不计入等级分', ko: '이 대국은 레이팅에 반영되지 않습니다', es: 'Esta partida no puntúa', fr: "Cette partie n'est pas classée", pt: 'Esta partida não conta para o ranking', de: 'Diese Partie wird nicht gewertet', hi: 'यह गेम रेटेड नहीं हुआ', ar: 'لم تُحتسب هذه المباراة في التصنيف' },
    legacy: { ja: 'この対局はレート対象外になりました', en: 'This game was not rated', zh: '本局不计入等级分', ko: '이 대국은 레이팅에 반영되지 않습니다', es: 'Esta partida no puntúa', fr: "Cette partie n'est pas classée", pt: 'Esta partida não conta para o ranking', de: 'Diese Partie wird nicht gewertet', hi: 'यह गेम रेटेड नहीं हुआ', ar: 'لم تُحتسب هذه المباراة في التصنيف' },
    open: { ja: '前のレート戦の結果を確定中です。確定するまで対戦相手は見つかりません', en: 'Your previous rated game is still being settled — matching starts once it is', zh: '上一局计分对局的结果仍在确认中，确认后才会开始匹配', ko: '이전 레이팅 대국의 결과를 확정하는 중입니다. 확정 후 매칭이 시작됩니다', es: 'Tu partida puntuable anterior aún se está cerrando; el emparejamiento empezará después', fr: "Votre partie classée précédente est en cours de validation ; l'appariement commencera ensuite", pt: 'Sua partida ranqueada anterior ainda está sendo confirmada; o pareamento começa depois', de: 'Deine vorige gewertete Partie wird noch abgerechnet – die Suche beginnt danach', hi: 'आपका पिछला रेटेड गेम अभी तय हो रहा है — उसके बाद मैच खोजा जाएगा', ar: 'ما زالت نتيجة مباراتك المصنّفة السابقة قيد التأكيد — تبدأ المطابقة بعد ذلك' },
    chatRate: { ja: 'チャットは3秒に1回までです', en: 'One chat message every 3 seconds', zh: '聊天每3秒最多一条', ko: '채팅은 3초에 한 번까지입니다', es: 'Un mensaje cada 3 segundos', fr: 'Un message toutes les 3 secondes', pt: 'Uma mensagem a cada 3 segundos', de: 'Eine Nachricht alle 3 Sekunden', hi: 'हर 3 सेकंड में एक संदेश', ar: 'رسالة واحدة كل 3 ثوانٍ' },
  };
  const lang = () => { const l = String(document.documentElement.lang || navigator.language || 'en').slice(0, 2).toLowerCase(); return M.void[l] ? l : 'en'; };
  const msg = k => (M[k] ? M[k][lang()] || M[k].en : '');
  // a small self-contained notice (pages have their own toasts with different names)
  function notice(k, ms) {
    const text = msg(k) || String(k || ''); if (!text) return;
    let el = document.getElementById('osec-note');
    if (!el) {
      el = document.createElement('div'); el.id = 'osec-note';
      el.style.cssText = 'position:fixed;left:50%;bottom:24px;transform:translateX(-50%);z-index:2147483000;max-width:min(92vw,520px);padding:10px 16px;border-radius:12px;background:rgba(20,20,24,.92);color:#fff;font:600 14px/1.45 system-ui,sans-serif;box-shadow:0 6px 24px rgba(0,0,0,.3);text-align:center;pointer-events:none;transition:opacity .25s';
      document.body.appendChild(el);
    }
    el.textContent = text; el.style.opacity = '1';
    clearTimeout(notice.t); notice.t = setTimeout(() => { el.style.opacity = '0'; }, ms || 4200);
  }

  window.OnlineSec = { FB, STALE, PAIR_MAX, WAIT, appCheck, detect, outcome, elo, kOf, make, xferOut, xferIn, msg, notice };
})();
